import { defineSchema } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  pokemon_cache: v.object({
    pokemonName: v.string(),
    runId: v.string(),
    name: v.string(),
    weight: v.number(),
  }),
});

import { query, mutation, action } from "./_generated/api";
import { v } from "convex/values";
import { internalQuery, internalMutation, internalAction } from "./_generated/server";

// Query to check if pokemon data is cached
export const getCachedPokemon = internalQuery({
  args: {
    pokemonName: v.string(),
    runId: v.string(),
  },
  handler: async (ctx, args) => {
    const cached = await ctx.db
      .query("pokemon_cache")
      .withIndex("by_pokemonName_runId", (q) =>
        q.eq("pokemonName", args.pokemonName).eq("runId", args.runId)
      )
      .first();
    return cached;
  },
});

// Mutation to store pokemon data in cache
export const cachePokemon = internalMutation({
  args: {
    pokemonName: v.string(),
    runId: v.string(),
    name: v.string(),
    weight: v.number(),
  },
  handler: async (ctx, args) => {
    await ctx.db.insert("pokemon_cache", {
      pokemonName: args.pokemonName,
      runId: args.runId,
      name: args.name,
      weight: args.weight,
    });
  },
});

// Action to fetch pokemon data (with caching)
export const getPokemon = internalAction({
  args: {
    pokemonName: v.string(),
    runId: v.string(),
  },
  handler: async (ctx, args) => {
    // Check cache first
    const cached = await ctx.runQuery(internal.api.getCachedPokemon, {
      pokemonName: args.pokemonName,
      runId: args.runId,
    });

    if (cached) {
      return cached;
    }

    // Fetch from PokeAPI
    const response = await fetch(
      `https://pokeapi.co/api/v2/pokemon/${args.pokemonName}`
    );

    if (!response.ok) {
      throw new Error(`Failed to fetch pokemon: ${response.statusText}`);
    }

    const data = await response.json();

    const result = {
      pokemonName: args.pokemonName,
      runId: args.runId,
      name: data.name,
      weight: data.weight,
    };

    // Store in cache
    await ctx.runMutation(internal.api.cachePokemon, {
      pokemonName: args.pokemonName,
      runId: args.runId,
      name: data.name,
      weight: data.weight,
    });

    return result;
  },
});

import { defineSchema } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  pokemon_cache: v
    .object({
      pokemonName: v.string(),
      runId: v.string(),
      name: v.string(),
      weight: v.number(),
    })
    .index("by_pokemonName_runId", ["pokemonName", "runId"]),
});

import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

// https://vite.dev/config/
export default defineConfig({
  plugins: [react()],
  define: {
    'import.meta.env.VITE_ZEALT_RUN_ID': JSON.stringify(process.env.ZEALT_RUN_ID || ''),
  },
})

import { useState } from "react";
import { useAction } from "convex/react";
import { api } from "../convex/_generated/api";

function App() {
  const [pokemonName, setPokemonName] = useState("");
  const [result, setResult] = useState<{
    name: string;
    weight: number;
  } | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const getPokemon = useAction(api.api.getPokemon);

  const handleFetch = async () => {
    if (!pokemonName.trim()) return;
    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const runId = import.meta.env.VITE_ZEALT_RUN_ID || "";
      const data = await getPokemon({
        pokemonName: pokemonName.trim().toLowerCase(),
        runId,
      });
      setResult({ name: data.name, weight: data.weight });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <h1>Pokemon Fetcher</h1>
      <div>
        <input
          type="text"
          id="pokemon-input"
          value={pokemonName}
          onChange={(e) => setPokemonName(e.target.value)}
          placeholder="Enter Pokemon name"
          onKeyDown={(e) => e.key === "Enter" && handleFetch()}
        />
        <button id="fetch-button" onClick={handleFetch} disabled={loading}>
          {loading ? "Fetching..." : "Fetch"}
        </button>
      </div>
      <div id="result-display">
        {error && <p style={{ color: "red" }}>{error}</p>}
        {result && (
          <div>
            <p>
              <strong>Name:</strong> {result.name}
            </p>
            <p>
              <strong>Weight:</strong> {result.weight}
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

export default App;

