import { v } from "convex/values";
import { action, internalQuery, internalMutation } from "./_generated/server";

// Internal query to check if pokemon data is cached
export const getCachedPokemon = internalQuery({
  args: {
    pokemonName: v.string(),
    runId: v.string(),
  },
  handler: async (ctx, args) => {
    const cached = await ctx.db
      .query("pokemon_cache")
      .withIndex("by_pokemonName_runId", (q) =>
        q.eq("pokemonName", args.pokemonName).eq("runId", args.runId)
      )
      .first();
    return cached;
  },
});

// Internal mutation to store pokemon data in cache
export const cachePokemon = internalMutation({
  args: {
    pokemonName: v.string(),
    runId: v.string(),
    name: v.string(),
    weight: v.number(),
  },
  handler: async (ctx, args) => {
    await ctx.db.insert("pokemon_cache", {
      pokemonName: args.pokemonName,
      runId: args.runId,
      name: args.name,
      weight: args.weight,
    });
  },
});

// Public action to fetch pokemon data (with caching)
export const getPokemon = action({
  args: {
    pokemonName: v.string(),
    runId: v.string(),
  },
  handler: async (ctx, args) => {
    // Check cache first
    const cached = await ctx.runQuery(internal.api.getCachedPokemon, {
      pokemonName: args.pokemonName,
      runId: args.runId,
    });

    if (cached) {
      return cached;
    }

    // Fetch from PokeAPI
    const response = await fetch(
      `https://pokeapi.co/api/v2/pokemon/${args.pokemonName}`
    );

    if (!response.ok) {
      throw new Error(`Failed to fetch pokemon: ${response.statusText}`);
    }

    const data = await response.json();

    const result = {
      pokemonName: args.pokemonName,
      runId: args.runId,
      name: data.name,
      weight: data.weight,
    };

    // Store in cache
    await ctx.runMutation(internal.api.cachePokemon, {
      pokemonName: args.pokemonName,
      runId: args.runId,
      name: data.name,
      weight: data.weight,
    });

    return result;
  },
});

